    candidates = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    sep = min(candidates, key=lambda c: abs(c - (w - 1) / 2))
    out_w = sep
    out = [[4] * out_w for _ in range(h)]
    for r in range(h):
        for c in range(out_w):
            if grid[r][c] in (4, 9) and c + sep + 1 < w and grid[r][c + sep + 1] == 4:
                out[r][c] = 3
    return out
